```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_read;
use std::collections::BTreeSet;

struct Node;

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        // An item's `id` is a digest computed by the parser, so it is safe to use as a store key.
        // Drop items the 'seen' store already knows, and repeats within this batch.
        let mut batch_ids: BTreeSet<String> = BTreeSet::new();
        let mut out = Vec::with_capacity(items.len());
        for item in items {
            if batch_ids.contains(&item.id) {
                continue;
            }
            if state_read::get(&item.id).is_some() {
                continue;
            }
            batch_ids.insert(item.id.clone());
            out.push(item);
        }
        out
    }
}

export!(Node);
